import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateCartWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateCartWorkflow(req.scope)
    .run({
      input: {
        id: "cart_123",
        region_id: "region_123",
        shipping_address: {
          first_name: "John",
          last_name: "Doe",
          address_1: "1234 Main St",
          city: "San Francisco",
          country_code: "US",
          postal_code: "94111",
          phone: "1234567890",
        },
        additional_data: {
          external_id: "123"
        }
      }
    })

  res.send(result)
}

